<?php
/**
 * Asset Loader Trait.
 *
 * Provides shared utility methods for loading Webpack assets and handling
 * merged JSON translations for React-based scripts.
 *
 * @package    PPADVP
 * @author     Dobrzepostawieni <contact@dobrzepostawieni.pl>
 * @copyright  2026 Dobrzepostawieni.pl
 * @license    GPL-3.0-or-later
 */

namespace PPADVP\Engine\Traits;

// Prevent direct file access.
if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

/**
 * Trait AssetLoader
 */
trait AssetLoader {

	/**
	 * Reads the .asset.php file dynamically generated by Webpack and appends cache buster.
	 *
	 * @param string             $asset_file_path Absolute path to the .asset.php file.
	 * @param array<int, string> $default_deps    Fallback dependencies.
	 * @return array{dependencies: array<int, string>, version: string} Asset configuration.
	 */
	protected function get_webpack_asset_config( string $asset_file_path, array $default_deps = array( 'wp-element', 'wp-components', 'wp-i18n' ) ): array {
		$config = array(
			'dependencies' => $default_deps,
			'version'      => \defined( 'PPADVP_VERSION' ) ? \PPADVP_VERSION : '1.0.0',
		);

		if ( \file_exists( $asset_file_path ) ) {
			$file_data = require $asset_file_path;
			if ( \is_array( $file_data ) ) {
				$config['dependencies'] = $file_data['dependencies'] ?? $config['dependencies'];
				$config['version']      = (string) ( $file_data['version'] ?? $config['version'] );
			}
		}

		$config['version'] = $this->append_cache_buster_suffix( $config['version'] );

		return $config;
	}

	/**
	 * Returns a cache-busted version string based on the active Freemius plan.
	 *
	 * @param string $version The original version string from Webpack.
	 * @return string The modified version string.
	 */
	private function append_cache_buster_suffix( string $version ): string {
		$suffix = 'free';

		if ( \function_exists( 'ppadvp_fs' ) && \ppadvp_fs()->can_use_premium_code() ) {
			$plan   = \ppadvp_fs()->get_plan_name();
			$suffix = \is_string( $plan ) && '' !== $plan ? $plan : 'pro';
		}

		return $version . '-' . $suffix;
	}

	/**
	 * Configures script translations and JSON merging for provided handles.
	 *
	 * @param string|string[] $handles           Single handle or array of script handles.
	 * @param string|null     $translations_path Optional catalog directory. Defaults to the Free catalog.
	 */
	protected function setup_translations( $handles, ?string $translations_path = null ): void {
		$handles           = (array) $handles;
		$action            = \is_admin() ? 'admin_enqueue_scripts' : 'wp_enqueue_scripts';
		$translations_path = $this->resolve_translations_path( $translations_path );

		\add_action(
			$action,
			function () use ( $handles, $translations_path ): void {
				foreach ( $handles as $handle ) {
					$this->set_script_translations_for_handle( $handle, $translations_path );
				}
			},
			99
		);

		\add_filter(
			'pre_load_script_translations',
			function ( $translations, $file, $handle, $domain ) use ( $handles, $translations_path ) {
				if ( ! \in_array( $handle, $handles, true ) || \PPADVP_TEXTDOMAIN !== $domain ) {
					return $translations;
				}
				return $this->merge_json_translations_logic( $translations, $handle, $domain, $translations_path );
			},
			10,
			4
		);
	}

	/**
	 * Binds translations to a specific script handle.
	 *
	 * @param string      $handle            The script handle.
	 * @param string|null $translations_path Optional catalog directory. Defaults to the Free catalog.
	 */
	protected function set_script_translations_for_handle( string $handle, ?string $translations_path = null ): void {
		\wp_set_script_translations(
			$handle,
			\PPADVP_TEXTDOMAIN,
			$this->resolve_translations_path( $translations_path )
		);
	}

	/**
	 * Merges split JSON translation files generated by WP-CLI into a single translation object.
	 *
	 * @param string|false|null $translations     The existing translations JSON string.
	 * @param string            $handle           The current script handle.
	 * @param string            $domain           The current text domain.
	 * @param string|null       $translations_path Optional catalog directory. Defaults to the Free catalog.
	 * @return string|false|null Merged JSON string or original value on failure.
	 */
	protected function merge_json_translations_logic( $translations, string $handle, string $domain, ?string $translations_path = null ) {
		$locale = \determine_locale();
		$dir    = $this->resolve_translations_path( $translations_path );
		$files  = \glob( $dir . '/' . $domain . '-' . $locale . '-*.json' );

		if ( ! \is_array( $files ) || empty( $files ) ) {
			return $translations;
		}

		$merged_messages = array();
		$base_data       = array();

		foreach ( $files as $json_file ) {
			$data = $this->read_json_translation_file( $json_file );

			if ( empty( $data ) ) {
				continue;
			}

			if ( empty( $base_data ) ) {
				$base_data = $data;
			}

			$merged_messages = \array_merge( $merged_messages, $data['locale_data']['messages'] );
		}

		if ( empty( $merged_messages ) ) {
			return $translations;
		}

		$base_data['locale_data']['messages'] = $merged_messages;
		$encoded                              = \wp_json_encode( $base_data );

		return false !== $encoded ? $encoded : $translations;
	}

	/**
	 * Resolves the catalog directory while keeping the Free path as the default.
	 *
	 * Premium callers may supply their stripped Pro catalog directory without
	 * introducing a Core dependency on Premium classes or paths.
	 *
	 * @param string|null $translations_path Optional catalog directory.
	 * @return string Absolute catalog directory without a trailing slash.
	 */
	private function resolve_translations_path( ?string $translations_path = null ): string {
		$default_path = \plugin_dir_path( \PPADVP_PLUGIN_ABSOLUTE ) . 'languages';
		$path         = null === $translations_path || '' === $translations_path ? $default_path : $translations_path;

		return \rtrim( $path, '/\\' );
	}

	/**
	 * Reads and decodes a local JSON translation file natively.
	 *
	 * @param string $file_path Absolute path to the JSON file.
	 * @return array<string, mixed> Decoded JSON data or empty array on failure.
	 */
	private function read_json_translation_file( string $file_path ): array {
		if ( ! \file_exists( $file_path ) || ! \is_readable( $file_path ) ) {
			return array();
		}

		// phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
		$content = \file_get_contents( $file_path );

		if ( empty( $content ) || ! \is_string( $content ) ) {
			return array();
		}

		$data = \json_decode( $content, true );

		if ( ! \is_array( $data ) || empty( $data['locale_data']['messages'] ) ) {
			return array();
		}

		return $data;
	}
}
